{
  "name": "@br4zz4/opencode-smart-tools",
  "version": "0.2.0",
  "description": "OpenCode TUI plugin with smart tools: /auto sends 'continue' and submits",
  "author": "oporpino <dev@porpi.no>",
  "license": "AGPL-3.0",
  "type": "module",
  "main": "./dist/index.js",
  "files": [
    "dist"
  ],
  "exports": {
    ".": "./dist/index.js",
    "./tui": "./dist/index.js"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "automation"
  ],
  "engines": {
    "opencode": ">=2.0.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "types": "./dist/index.js",
  "scripts": {
    "build": "node build.mjs",
    "prepublishOnly": "npm run build",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.29",
    "@opentui/solid": "0.4.5",
    "@types/node": "^26.4.1",
    "esbuild": "^0.28.2",
    "solid-js": "^1.9.0",
    "typescript": "5.8.2"
  }
}
